// Vendors Leaflet's dist JS/CSS into a plain JS module so the crew app's
// offline map page can embed it inline — no CDN request, so the map loads
// with zero connectivity. Re-run after bumping the `leaflet` dev dependency:
//
//   npm run build:leaflet
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const pkgPath = require.resolve('leaflet/package.json');
const dist = join(dirname(pkgPath), 'dist');
const { version } = JSON.parse(readFileSync(pkgPath, 'utf8'));

// The page is inlined into a <script>/<style>, so neutralise any closing tag.
const js = readFileSync(join(dist, 'leaflet.js'), 'utf8').replace(/<\/script/gi, '<\\/script');
const css = readFileSync(join(dist, 'leaflet.css'), 'utf8').replace(/<\/style/gi, '<\\/style');

const out = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'lib', 'offlineMap', 'leafletBundle.js');
writeFileSync(
  out,
  `// GENERATED by scripts/build-leaflet-bundle.mjs — do not edit by hand.
// Leaflet ${version} (BSD-2-Clause, https://leafletjs.com), vendored for offline use.
export const LEAFLET_VERSION = ${JSON.stringify(version)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
export const LEAFLET_JS = ${JSON.stringify(js)};
`
);
console.log(`Wrote Leaflet ${version} bundle -> ${out}`);
